def second_largest_distinct(nums):
    first = None
    second = None
    for x in nums:
        if first is None or x > first:
            if x != first:
                second = first
                first = x
        elif x != first and (second is None or x > second):
            second = x
    return second

def is_valley(nums):
    if len(nums) < 3:
        return False
    i = 1
    while i < len(nums) and nums[i] < nums[i - 1]:
        i += 1
    if i == 1 or i == len(nums):
        return False
    while i < len(nums) and nums[i] > nums[i - 1]:
        i += 1
    return i == len(nums)

def first_pair_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        need = target - x
        if need in seen:
            return [seen[need], i]
        if x not in seen:
            seen[x] = i
    return []

def longest_unique(text):
    last = {}
    left = 0
    best = 0
    for right, ch in enumerate(text):
        if ch in last and last[ch] >= left:
            left = last[ch] + 1
        last[ch] = right
        best = max(best, right - left + 1)
    return best

def range_sums(nums, queries):
    prefix = [0]
    for x in nums:
        prefix.append(prefix[-1] + x)
    return [prefix[r + 1] - prefix[l] for l, r in queries]
